const clientSelect=document.getElementById('quote-client'),siteSelect=document.getElementById('quote-sites');
if(clientSelect&&siteSelect){const filterSites=(clear=true)=>siteSelect.querySelectorAll('option').forEach(option=>{const visible=option.dataset.client===clientSelect.value;option.hidden=!visible;option.disabled=!visible;if(clear&&!visible)option.selected=false});clientSelect.addEventListener('change',()=>filterSites(true));filterSites(false)}
const leadSource=document.getElementById('lead-source'),campaignField=document.getElementById('campaign-field');if(leadSource&&campaignField){const toggleCampaign=()=>campaignField.hidden=leadSource.value!=='campaign';leadSource.addEventListener('change',toggleCampaign);toggleCampaign()}
